contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient, bool freezeSender, uint256 amount) public {
        c.freezeAccount(address(this), true); if (__ESBMC_reverted()) return;
        uint256 balSenderBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 balRecipientBefore = c.balanceOf(recipient); if (__ESBMC_reverted()) return;
        uint256 totalSupplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.transfer(recipient, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c.balanceOf(address(this)) == balSenderBefore && c.balanceOf(recipient) == balRecipientBefore && c.totalSupply() == totalSupplyBefore);
    }

    receive() external payable {}
}

