pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address recipient, bool freezeSender, uint256 amount) internal {
        try c.freezeAccount(address(this), true) {} catch { return; }
        uint256 balSenderBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balSenderBefore = __r; } catch { return; }
        uint256 balRecipientBefore;
        try c.balanceOf(recipient) returns (uint256 __r) { balRecipientBefore = __r; } catch { return; }
        uint256 totalSupplyBefore;
        try c.totalSupply() returns (uint256 __r) { totalSupplyBefore = __r; } catch { return; }
        bool reverted;
        try c.transfer(recipient, amount) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && c.balanceOf(address(this)) == balSenderBefore && c.balanceOf(recipient) == balRecipientBefore && c.totalSupply() == totalSupplyBefore);
    }

    function testFuzz_run(address recipient, bool freezeSender, uint256 amount) public {
        vm.assume(recipient.code.length == 0 && uint160(recipient) > 0xffff && recipient != address(this) && recipient != address(c) && recipient != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && recipient != 0x000000000000000000636F6e736F6c652e6c6f67 && recipient != 0x4e59b44847b379578588920cA78FbF26c0B4956C && recipient != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(recipient, freezeSender, amount);
    }

    receive() external payable {}
}
